CREATE OR REPLACE VIEW `vwenasarcoprovv` AS select year(`p`.`data_fattura`) AS `competenza`,quarter(`p`.`data_fattura`) AS `Trimestre`,`p`.`denominazione_riferimento` AS `produttore`,`f`.`enasarco` AS `enasarco`,`p`.`importo` AS `montante`,((`p`.`importo` * (`e`.`aliquota_agente` + `e`.`aliquota_soc`)) / 100) AS `contributo` from ((`provvigioni` `p` join `fornitoris` `f` on((`f`.`piva` = `p`.`piva`))) join `enasarcos` `e` on(((`e`.`competenza` = year(`p`.`data_fattura`)) and (`e`.`enasarco` = `f`.`enasarco`)))) where ((`p`.`stato` is not null) and (`p`.`data_fattura` is not null) and (`p`.`stato` <> 'Annullato') and (`p`.`entrata_uscita` = 'Uscita'))
